import Foundation

enum TranslationKey: String, CaseIterable, Hashable {
    case sidebarMonitor, sidebarWorkspace, dashboardIntro, monitoringLive, monitoringPaused, settingsIntro, selectedOption
    case noSearchResults, noSearchResultsDetail, clearSearch, cacheCandidateDetail, scanPartial, openSystemSettings
    case dashboard, recommendations, processes, storage, developerTools, history, settings
    case performanceOverview, liveMetrics, refresh, cpu, memoryState, storageCapacity, thermalState
    case temperatureCelsius, temperatureUnavailable, thermalTempUnavailable, smartBoost, boostDescription
    case scanAndReview, reviewFindings, noFindings, noRecommendations, recommendationsIntro
    case healthy, attention, critical, unavailable, metricsUnavailable, measurementLimitations
    case readingMetrics, sampling, needsIntervalSample, user, system, physical, appEstimate, swap
    case storageUnavailable, available, used, nominal, fair, serious, macOSThermalState, openSection
    case lowStorageTitle, lowStorageDetail, highMemoryTitle, highMemoryDetail, highCPUTitle, highCPUDetail
    case elevatedThermalTitle, elevatedThermalDetail
    case runningApplications, processDetails, application, pid, memoryFootprint, action, quit
    case protectedProcess, quitWarning, quitConfirmation, cancel, identityChanged, quitRequested, quitFailed
    case identityChangedEnglish, quitRequestedEnglish, quitFailedEnglish, quitObservedEnglish, quitStillRunningEnglish, processCPUUnavailable
    case quitObserved, quitStillRunning, evidenceStorage, evidenceThermal, evidenceMemoryEstimated, evidenceMemoryFallback, evidenceCPU
    case emptyProcesses, emptyProcessesDetail, searchApplications
    case storageAnalysis, storageIntro, volumeCapacity, cacheScan, cacheScanDescription, scanCaches, scanning
    case foldersAnalyzed, noScanResults, noScanResultsDetail, reviewRequired, removalNotImplemented
    case developerIntegration, developerIntegrationDetails, nodeJS, npm, pnpm, yarn, homebrew, docker, xcode
    case commonInstallPaths, notFound, developerIntegrationLimitations
    case noHistory, noHistoryDetail, historySummary, historyPrivacy, clearHistory, clearHistoryConfirmation, clearHistoryMessage
    case cacheScanCompleted, cacheScanPartial, gracefulQuitRequested, gracefulQuitNotAccepted, estimatedData, activityRecorded
    case settingsPerformance, monitorWhileOpen, refreshInterval, seconds
    case appearance, systemTheme, lightTheme, darkTheme, accentColor, themeOcean, themeViolet, themeEmerald, themeRose, themeChangeNote
    case startupLoginItems, startupLoginItemsIntro, loginItemsSettingsButton, loginItemsWhere, loginItemsWhereDetail
    case openAtLogin, openAtLoginDetail, backgroundItems, backgroundItemsDetail, loginItemsLimits, loginItemsLimitsDetail
    case systemSettingsOpenFailed, loginItemsNoChanges
    case language, languageRestartNote, privacy, localOnly, privacyDetails, limitations, settingsLimitations
    case about, version, macOSVersion
}

func localized(_ key: TranslationKey, language: AppLanguage) -> String {
    switch language {
    case .english: english[key] ?? key.rawValue
    case .bangla: bangla[key] ?? english[key] ?? key.rawValue
    case .arabic: arabic[key] ?? english[key] ?? key.rawValue
    }
}

